    tenure: ri(8, 25),
    smarts: ri(70, 95),
    justHired: false,
    country: pick(COWORKER_COUNTRIES),
    tier: 'boss',
  });
  // Senior (3)
  for(let i=0; i<3; i++){
    list.push({
      name: pick(COWORKER_FIRST)+' '+pick(COWORKER_LAST),
      age: ri(35, 55),
      position: pos.senior[i % pos.senior.length],
      morale: ri(45, 90),
      fitness: ri(45, 85),
      tenure: ri(4, 15),
      smarts: ri(60, 90),
      justHired: pct(0.05),
      country: pick(COWORKER_COUNTRIES),
      tier: 'senior',
    });
  }
  // Regular (8)
  for(let i=0; i<8; i++){
    list.push({
      name: pick(COWORKER_FIRST)+' '+pick(COWORKER_LAST),
      age: ri(22, 45),
      position: pos.regular[i % pos.regular.length],
      morale: ri(35, 90),
